using Xunit; using ClipSync.Core;
public class ProtocolTests { [Fact] public void Vectors(){var path=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"..","..","..","..","..","core-spec","protocol-test-vectors.json"));var j=System.Text.Json.JsonDocument.Parse(File.ReadAllText(path));foreach(var v in j.RootElement.GetProperty("frames").EnumerateArray()){if(v.GetProperty("name").GetString()=="multi-frame") continue;var hex=v.GetProperty("hex").GetString()!;if(v.TryGetProperty("error",out _))Assert.Throws<InvalidDataException>(()=>FrameCodec.Decode(Convert.FromHexString(hex)));else {var m=FrameCodec.Decode(Convert.FromHexString(hex));Assert.Equal(v.GetProperty("parsed").GetProperty("type").GetString(),m.Type.ToString().ToUpperInvariant());}}} [Fact] public void SplitsAndMulti(){var r=new FrameReader();var f=FrameCodec.Encode(new(MessageType.Text,"hello"));Assert.Empty(r.Push(f[..4].ToArray()));Assert.Single(r.Push(f[4..].ToArray()));var both=FrameCodec.Encode(new(MessageType.Ack)).Concat(FrameCodec.Encode(new(MessageType.Ping))).ToArray();Assert.Equal(2,r.Push(both).Count());} [Fact] public void GuardsLamportPendingScheduler(){var seen=new HashSet<string>();Assert.True(HashGuard.ShouldApply("a",null,seen));Assert.False(HashGuard.ShouldApply("a","a",seen));var a=new ClipVersion(1,"a","a",new(MessageType.Image,Bytes:new byte[]{1}));var b=new ClipVersion(2,"b","b",new(MessageType.Text,"x"));var p=new PendingSlot();p.Put(a);p.Put(b);Assert.Equal(b,p.Take());var s=new SendScheduler();s.Offer(a);s.Offer(b);Assert.Equal(b,s.Next());} [Fact] public void TieBreak(){var a=new ClipVersion(4,"a","a",new(MessageType.Text,"a"));var b=new ClipVersion(4,"b","b",new(MessageType.Text,"b"));Assert.True(b.CompareTo(a)>0);} [Fact] public void EngineCases(){var e=new SyncEngine();var img=new ClipVersion(1,"a","img",new(MessageType.Image,Bytes:new byte[]{1}));var txt=new ClipVersion(2,"a","txt",new(MessageType.Text,"new"));e.Local(img);e.Local(txt);Assert.Equal(txt,e.Pending.Take());e.Connect();e.Local(img);e.Local(txt);Assert.Equal(txt,e.Scheduler.Next());Assert.True(e.Apply(txt));Assert.False(e.Apply(txt));e.Pause();Assert.Equal(EngineState.Paused,e.State);e.Resume();Assert.Equal(EngineState.Connected,e.State);} }

